    contentHtml: `<!-- target keyword: 십이지지 | secondary: 지장간, 사주 충합형, 월지 -->
<p>십이지지(十二地支)는 자(子)·축(丑)·인(寅)·묘(卯)·진(辰)·사(巳)·오(午)·미(未)·신(申)·유(酉)·술(戌)·해(亥) 열두 개의 부호로, 사주에서 계절·환경·현실 무대를 나타냅니다. 천간이 겉으로 드러나는 지향이라면 지지는 그 기운이 놓인 땅의 조건이며, 특히 월지(月支)는 일간의 강약을 결정하는 가장 중요한 변수입니다.</p>
<h2>십이지지란: 띠 동물이 아니라 환경 정보</h2>
<p>많은 분이 지지를 띠 동물의 성격 정도로 알고 있지만, 명리에서 지지는 시간과 공간의 배경 정보입니다. 같은 갑목(甲木) 일간이라도 봄의 인·묘월에 태어나면 기운이 왕성하고, 가을의 신·유월에 태어나면 뿌리가 약해집니다. 천간의 성향이 어떤 무대 위에서 펼쳐지는지를 알려 주는 것이 지지의 역할입니다. 천간 열 글자의 기질이 아직 낯설다면 <a href="/insights/ten-heavenly-stems-practical/">십천간 해석 가이드</a>를 먼저 읽어 두면 이 글이 훨씬 쉬워집니다.</p>
<h2>계절로 묶어 읽는 십이지지</h2>
<p>지지 열두 개는 세 개씩 네 계절로 묶입니다. 이 묶음만 외워도 사주의 온도와 기세를 한눈에 가늠할 수 있습니다.</p>
<ul>
  <li>봄 — 인(寅)·묘(卯)·진(辰): 목(木) 기운, 시작·성장·추진</li>
  <li>여름 — 사(巳)·오(午)·미(未): 화(火) 기운, 열정·표현·확장</li>
  <li>가을 — 신(申)·유(酉)·술(戌): 금(金) 기운, 결실·결단·정리</li>
  <li>겨울 — 해(亥)·자(子)·축(丑): 수(水) 기운, 저장·성찰·회복</li>
</ul>
<p>각 계절의 마지막 글자인 진·미·술·축은 토(土)로, 계절을 마무리하고 다음 계절로 넘겨주는 환절기 창고 역할을 합니다.</p>
<h2>지장간: 지지 속에 숨은 천간</h2>
<p>지장간(地藏干)은 각 지지 안에 갈무리된 천간을 말합니다. 예를 들어 자(子) 속에는 임수·계수가, 인(寅) 속에는 무토·병화·갑목이 들어 있습니다. 지장간을 알아야 일간이 지지에 뿌리를 내렸는지(통근)를 판별할 수 있고, 통근 여부는 신강신약 판단의 핵심 근거가 됩니다.</p>
<p>겉으로 보이지 않던 오행이 지장간에 숨어 있는 경우도 많아, 지장간을 빼고 읽으면 사주 해석의 상당 부분을 놓치게 됩니다. 표면의 여덟 글자와 지장간을 함께 볼 때 비로소 팔자의 실제 무게 배분이 보입니다.</p>
<h2>충·합·형·파·해: 지지끼리의 상호작용</h2>
<p>지지 사이에는 여러 관계가 성립합니다. 충(沖)은 자오충·인신충처럼 정반대 기운이 부딪혀 변화 압력을 만들고, 합(合)은 자축합·인해합처럼 두 기운이 결속해 새로운 오행의 기세를 만들기도 합니다. 형(刑)은 마찰과 정비 과제, 파(破)는 균열, 해(害)는 방해 에너지로 요약됩니다.</p>
<p>중요한 것은 이 관계들을 공포의 언어로 쓰지 않는 것입니다. 세운에서 내 일지와 충이 온다면 "관계가 끊긴다"가 아니라 "환경 변화 가능성이 커지니 경계와 소통 규칙을 재점검할 시기"로 번역하는 것이 정확하고 실용적입니다.</p>
<h2>월지: 사주에서 가장 힘이 센 지지</h2>
<p>월지는 태어난 계절의 기운을 담고 있어 팔자 전체 기세의 저울추 역할을 합니다. 월지가 일간을 생해 주는 인성이면 환경이 나를 지원하는 구조이고, 일간을 극하는 관성이면 외부 압박이 큰 구조입니다. 월지를 얻어 득령(得令)하면 일간이 강해지고, 계절을 거스르면 약해집니다. 이 판단은 용신 선정의 출발점이기도 하니, 다음 단계는 <a href="/insights/yongshin-how-to-think/">용신 찾는 법</a>으로 이어서 보세요.</p>
<h2>십이지지를 일상에 적용하는 법</h2>
<p>가장 실용적인 활용은 올해 세운의 지지와 내 일지·월지의 관계를 확인하는 것입니다. 합이 많은 해는 협력과 결속의 기회가 모이고, 충이 오는 해는 변화 대비와 정리가 유리합니다. 이론 암기보다 "내 사주에서 이 지지가 어떻게 작동하는가"를 연결해 읽을 때 지지는 두려운 기호가 아니라 환경을 읽는 지도가 됩니다. 전체 구조가 궁금하다면 <a href="/insights/saju-four-pillars-basics/">사주팔자 기초 가이드</a>와 함께 보세요.</p>
<p><strong>내 사주의 지지 구성과 충합 관계가 궁금하다면</strong> <a href="/manse/">무료 만세력</a>으로 팔자를 뽑고 <a href="/saju/">사주 분석</a>에서 연이의 해석을 받아 보세요.</p>`,
