    useOriginalContent: true,
    contentHtml: `<p>자미두수에서 자미성(紫微星)은 모든 별의 중심이며, 북극성을 상징하는 제왕(帝王)의 별입니다. 사주명리학에서 일간(日干)이 자신을 나타낸다면, 자미두수에서는 자미성이 가장 강력한 리더십과 통솔력을 상징하는 핵심 주성(主星)입니다.</p>
<p>자미성은 단순히 높은 지위만 의미하지 않습니다. 자신의 삶을 스스로 통제하고, 책임을 지며, 사람을 이끄는 힘을 뜻합니다.</p>
<h2>1. 자미성의 기본 의미</h2>
<table>
<thead><tr><th>구분</th><th>의미</th></tr></thead>
<tbody>
<tr><td>오행</td><td>토(土)</td></tr>
<tr><td>음양</td><td>음토(陰土)</td></tr>
<tr><td>상징</td><td>황제, 왕, 최고지도자</td></tr>
<tr><td>성격</td><td>존엄, 권위, 품격</td></tr>
<tr><td>키워드</td><td>리더십, 책임감, 통솔력, 명예</td></tr>
</tbody>
</table>
<p>자미성은 하늘의 황궁을 의미하는 별입니다. 그래서 이 별을 가진 사람은 중심에 서려는 기질, 큰 그림을 보는 능력, 책임지는 성향, 사람을 관리하는 능력이 매우 뛰어납니다.</p>
<h2>2. 자미성의 성격</h2>
<h3>① 품격이 있다</h3>
<p>자미성은 행동이 점잖습니다. 가볍게 행동하지 않습니다. 항상 "내 위치에서 어떻게 행동해야 하는가"를 먼저 생각합니다.</p>
<h3>② 리더십</h3>
<p>자미성은 명령하기보다 사람들이 자연스럽게 따르게 만드는 힘이 있습니다. 억지 권력이 아니라 존경받는 리더입니다.</p>
<h3>③ 책임감</h3>
<p>맡은 일은 끝까지 합니다. 도망가는 성격이 아닙니다.</p>
<h3>④ 자존심</h3>
<p>자존감이 높은 편입니다. 다만 자존심이 지나치면 고집으로 변할 수 있습니다.</p>
<h3>⑤ 체면을 중요하게 생각</h3>
<p>명예를 잃는 것을 가장 싫어합니다. 신뢰가 매우 중요합니다.</p>
<h2>3. 자미성의 장점</h2>
<p>대표적인 장점은 통솔력, 리더십, 책임감, 신뢰, 명예, 조직관리, 전략, 포용력, 인내심, 큰 그릇입니다. 특히 조직을 운영하는 능력이 뛰어납니다.</p>
<h2>4. 자미성의 단점</h2>
<p>아무리 좋은 별도 단점은 있습니다.</p>
<ul>
<li>권위주의 — 내 방식이 맞다고 생각하기 쉽습니다.</li>
<li>고집 — 결정을 바꾸기 어렵습니다.</li>
<li>외로움 — 책임이 큰 만큼 혼자 고민하는 일이 많습니다.</li>
<li>완벽주의 — 기준이 높습니다. 자신에게도 엄격합니다.</li>
</ul>
<h2>5. 자미성이 강하면</h2>
<p>자미성이 강한 사람은 리더, 대표, 관리자, 정치인, CEO, 교수, 기관장처럼 사람을 이끄는 위치에 오르는 경우가 많습니다.</p>
<h2>6. 자미성이 약하면</h2>
<p>자미성이 약하거나 흉성의 영향을 많이 받으면 우유부단, 권위 부족, 자신감 부족, 책임 회피, 리더십 부족으로 나타날 수 있습니다.</p>
<h2>7. 자미성의 인간관계</h2>
<p>자미성은 많은 친구보다 좋은 사람을 오래 만나는 스타일입니다. 의리를 중요하게 생각합니다.</p>
<h2>8. 자미성의 연애</h2>
<p>연애에서도 신뢰를 가장 중요하게 생각합니다. 쉽게 사랑하지 않고, 오래 사귀며, 책임감이 있고, 결혼을 전제로 연애하며, 배신을 매우 싫어합니다.</p>
<h2>9. 자미성의 결혼</h2>
<p>결혼 후에는 가정을 책임지는 배우자가 됩니다. 다만 가끔은 상대를 통제하려는 경향이 나타날 수 있습니다.</p>
<h2>10. 자미성의 재물운</h2>
<p>재물운은 상당히 좋은 편입니다. 하지만 단기투기보다 장기적인 자산관리에 강합니다. 재물 스타일은 부동산, 장기투자, 기업 운영, 안정적 자산입니다.</p>
<h2>11. 자미성의 직업운</h2>
<p>가장 잘 맞는 직업은 관리·기업 대표·임원·공무원·군인·경찰 간부 같은 전문직, 의사·변호사·교수·회계사, 경영·CEO·창업가·기관장, 교육·강사·교육기관 운영입니다.</p>
<h2>12. 자미성의 건강운</h2>
<p>주의할 부분은 위장, 소화기, 비장, 스트레스, 혈압입니다. 과로를 피하는 것이 중요합니다.</p>
<h2>13. 자미성과 부모</h2>
<p>부모복이 좋은 경우가 많습니다. 다만 부모의 기대가 클 수도 있습니다.</p>
<h2>14. 자미성과 자녀</h2>
<p>자녀에게 책임감 있는 부모입니다. 교육에 관심이 많습니다.</p>
<h2>15. 자미성과 귀인운</h2>
<p>자미성은 귀인의 도움을 받는 별로도 알려져 있습니다. 특히 나이가 들수록 높은 위치의 사람들과 인연이 생기기 쉽습니다.</p>
<h2>16. 자미성의 성공 방식</h2>
<p>자미성은 빨리 성공하는 별이 아닙니다. 천천히 올라가지만 한 번 정상에 오르면 오래 유지합니다.</p>
<h2>17. 자미성과 다른 주성과의 조합</h2>
<p>자미성은 단독으로도 강력하지만, 함께 있는 주성에 따라 성향이 달라집니다.</p>
<table>
<thead><tr><th>조합</th><th>특징</th></tr></thead>
<tbody>
<tr><td>자미 + 천부</td><td>안정적인 리더, 재물과 관리 능력이 뛰어남</td></tr>
<tr><td>자미 + 천상</td><td>품격과 명예를 중시하는 지도자형, 공정성과 중재 능력이 뛰어나 조직 관리에 유리</td></tr>
<tr><td>자미 + 탐랑</td><td>사교성과 매력이 더해져 대외 활동에 강함</td></tr>
<tr><td>자미 + 칠살</td><td>결단력과 추진력이 강하지만 갈등도 많아질 수 있음</td></tr>
<tr><td>자미 + 파군</td><td>변화와 개혁을 이끄는 혁신형 리더</td></tr>
</tbody>
</table>
<h2>18. 자미성이 위치한 궁의 의미</h2>
<p>자미성은 어느 궁(宮)에 위치하느냐에 따라 해석이 달라집니다.</p>
<ul>
<li>명궁 — 강한 자존감과 리더십, 인생 전반의 중심 역할.</li>
<li>관록궁 — 직업에서 높은 직위나 관리직에 오를 가능성.</li>
<li>재백궁 — 안정적인 재물 축적과 자산 관리 능력.</li>
<li>부처궁 — 배우자가 책임감 있고 사회적 기반이 탄탄한 경우가 많음.</li>
<li>천이궁 — 외부 활동과 사회적 평판에서 강점을 발휘.</li>
<li>복덕궁 — 정신적 여유와 품격을 중시하는 삶의 태도.</li>
</ul>
<h2>19. 자미성의 개운법</h2>
<p>자미성의 장점을 더욱 살리기 위해서는 다음과 같은 습관이 도움이 된다고 전통적으로 해석합니다.</p>
<ul>
<li>책임을 회피하지 않고 끝까지 완수하기.</li>
<li>장기적인 목표를 세워 꾸준히 실행하기.</li>
<li>권위보다 배려와 경청을 함께 실천하기.</li>
<li>신뢰를 기반으로 인간관계를 유지하기.</li>
<li>단기 성과보다 명예와 평판을 소중히 여기기.</li>
</ul>
<h2>20. 자미성 총평</h2>
<p>자미성은 자미두수의 중심이 되는 '황제의 별'로, 권위와 명예, 책임감, 통솔력을 상징합니다. 사람을 이끄는 능력과 조직을 안정적으로 운영하는 자질이 뛰어나며, 시간이 지날수록 역량과 영향력이 커지는 경우가 많습니다.</p>
<p>다만 자미두수에서는 자미성 하나만으로 운명을 판단하지 않습니다. 명궁, 신궁, 12궁의 배치, 보조성(길성·흉성), 사화(化祿·化權·化科·化忌), 대운과 유년운 등을 함께 종합해야 보다 정확한 해석이 가능합니다.</p>
<p>따라서 자미성은 "리더십과 중심성"이라는 큰 틀의 상징으로 이해하고, 실제 운세 해석에서는 전체 명반의 구조를 함께 살펴보는 것이 자미두수의 정통적인 접근입니다.</p>`,
