    description: "천부성은 자미두수에서 재물·안정·신뢰·포용력을 대표하는 길성입니다. 기본 의미부터 성격·장단점·재물운·직업운·궁위별 해석·다른 주성과의 조합·개운법까지 정리했습니다.",
