<p>이 수많은 별 가운데 가장 중요한 것이 바로 14주성(十四主星)이다. 14주성은 명반의 중심축을 이루는 핵심 별로서, 사람의 기질과 가치관, 행동 방식, 직업 성향, 인간관계, 삶의 방향을 결정하는 가장 중요한 요소다.</p>
