<p>그러나 주성의 의미는 결코 고정되어 있지 않다. 궁의 위치, 별의 조합, 사화의 작용, 대운과 세운의 흐름에 따라 같은 별도 전혀 다른 모습으로 발현될 수 있다. 따라서 자미두수를 깊이 이해하려면 14주성을 개별적인 성격 유형으로 암기하는 데 그치지 말고, 명반 전체 속에서 서로 연결되고 변화하는 하나의 유기적인 체계로 이해해야 한다.</p>
