    contentHtml: `<!-- target keyword: 숙요점 궁합 | secondary: 27수 궁합, 본명숙, 영친 안괴 -->
<p>숙요점 궁합은 태어난 날 달이 머문 자리인 27수(宿)로 두 사람의 관계 리듬을 읽는 방법입니다. 내 본명숙과 상대 본명숙 사이의 거리·관계 유형을 확인하면, 왜 어떤 사람과는 대화가 술술 풀리고 어떤 사람과는 늘 반 박자 어긋나는지가 구조적으로 보입니다.</p>
<h2>숙요점 궁합의 원리: 달의 자리로 읽는 관계</h2>
<p>숙요점(宿曜占)은 달의 궤도를 27개의 수(宿)로 나누고, 태어난 날 달이 어느 수에 있었는지로 그 사람의 본명숙(本命宿)을 정합니다. 궁합은 두 본명숙 사이의 상대적 위치 관계로 읽는데, 태양 별자리보다 잘게 나뉜 달 기반 체계라 감정의 결과 소통 템포처럼 일상적인 케미를 읽는 데 강합니다. 27수 체계 자체가 처음이라면 <a href="/insights/sukuyo-lunar-mansion-primer/">숙요점 완전 입문</a>을 먼저 읽어 두면 이 글이 두 배로 쉬워집니다.</p>
<h2>핵심 관계 유형: 영친·업태·안괴</h2>
<p>숙요 궁합의 대표적인 관계 유형 세 가지를 기억하세요.</p>
<ul>
  <li><strong>영친(栄親)</strong>: 서로를 빛나게 하고 돌보는 관계 — 함께 있으면 성장과 안정감이 커지는 대표적인 길연입니다.</li>
  <li><strong>업태(業胎)</strong>: 전생의 인연에 비유되는 깊은 끌림의 관계 — 강하게 끌리지만 익숙한 패턴이 반복되기 쉬워, 관계를 '반복'이 아닌 '완성'으로 끌고 가는 의식적 노력이 포인트입니다.</li>
  <li><strong>안괴(安壊)</strong>: 편안함(安)과 흔들림(壊)이 공존하는 관계 — 처음엔 강렬하게 통하지만 리듬이 어긋나기 시작하면 소모가 커지는 조합으로, 규칙 설계가 가장 필요한 유형입니다.</li>
</ul>
<p>중요한 것은 안괴라고 해서 '만나면 안 되는 인연'이 아니라는 점입니다. 어긋나는 지점이 예측 가능하다는 뜻이므로, 오히려 대비가 가능한 관계입니다.</p>
<h2>거리 분류: 근거리·중거리·원거리</h2>
<p>같은 관계 유형이라도 두 본명숙의 거리(근거리·중거리·원거리)에 따라 체감이 달라집니다. 근거리는 자주 부딪히며 빠르게 가까워지는 대신 마찰도 잦고, 원거리는 서로를 객관적으로 보며 존중하기 좋은 대신 밀도를 만드는 데 시간이 걸립니다. 거리 감각의 자세한 해설은 <a href="/insights/sukuyo-three-group-types-guide/">숙요점 3분류 이해</a>에서 이어집니다.</p>
<h2>궁합을 관계 리듬으로 번역하기</h2>
<p>숙요 궁합의 실전 가치는 판정이 아니라 리듬 맞추기입니다. 유형을 확인했다면 다음 세 질문으로 번역해 보세요.</p>
<ul>
  <li>갈등이 생기면 누가 먼저 말문을 여는가 — 회복 개시자의 역할 합의</li>
  <li>감정 회복까지 걸리는 시간이 서로 얼마나 다른가 — 냉각 시간의 존중</li>
  <li>중요한 결정은 어떤 방식으로 합의하는가 — 즉답형과 숙고형의 절충</li>
</ul>
<p>이 세 가지만 맞춰도 안괴형 조합의 소모가 크게 줄고, 영친형 조합은 안정감에 성장 자극까지 더해집니다. 일주일 동안 연락 빈도와 대화 시간대를 바꿔 보는 리듬 실험도 좋은 방법입니다. 항목별 점검표는 <a href="/insights/sukuyo-compatibility-simple-checklist/">숙요점 궁합 체크리스트 7가지</a>에 정리되어 있습니다.</p>
<h2>숙요 궁합을 안전하게 쓰는 선</h2>
<p>업태·안괴 같은 단어는 인상이 강해서 관계를 단정하는 데 쓰이기 쉽습니다. 하지만 숙요 궁합은 운명 판정이 아니라 두 사람의 기본 리듬 차이를 미리 아는 지도입니다. 같은 조합이라도 소통 규칙과 신뢰의 축적에 따라 전혀 다른 관계가 된다는 전제를 잊지 마세요.</p>
<p><strong>내 본명숙과 상대의 관계 유형이 궁금하다면</strong> <a href="/sukuyo/">무료 숙요점 보기</a>에서 생년월일만으로 바로 확인할 수 있습니다. 사주·타로 궁합과 교차로 보고 싶다면 <a href="/compatibility/">무료 궁합 분석</a>도 함께 활용해 보세요.</p>`,
