    description: "연애 갈등은 대부분 사랑이 부족해서가 아니라 표현 방식의 차이에서 생깁니다. 숙요점 연애 소통 3원칙과 영친·업태·안괴·명성·위성·우쇠 6유형별 연애 소통법을 정리했습니다.",
