    slug: "sukuyo-27-guardian-animals-origin-guide",
    title: "27숙 수호동물 유래 가이드 — 왜 수호동물이 생겼는가, 역사적 근거는 무엇인가",
    description: "27숙 수호동물은 원전(나크샤트라·숙요경·이십팔수·숙요도)에 명시되지 않은 후대의 상징 해석입니다. 인도 나크샤트라 요니 체계와 한국식 동물 상징표를 함께 비교하고, 무엇이 역사적 근거가 있고 무엇이 없는지 정리했습니다.",
    category: "숙요점",
