    description: "78장 중 56장을 차지하는 마이너 아르카나는 4원소와 숫자의 조합입니다. 완드·컵·소드·펜타클의 원소 대응, 숫자가 만드는 공통 서사, 수트가 몰려 나올 때 읽는 법을 정리했습니다.",
