    description:
      "주역과 사주명리, 자미두수는 각각 어떤 질문에 답하는 도구일까요? 베다점성술의 낙샤트라 체계부터 헤이안 시대 일본에서 독자적으로 발달한 슈쿠요도, 한국과 일본의 택일 풍속까지 — 아시아의 점복 전통이 시간과 인연을 읽어온 방식을 체계적으로 비교해 깊이 있게 정리했습니다.",
