    description:
      "타로는 15세기 이탈리아 귀족의 카드놀이에서, 룬 점은 20세기의 현대적 재구성에서 출발했습니다. 유럽 점복 전통의 실제 역사와 상징 해석의 원리, 타로·룬·찻잎점을 제대로 읽는 실전 방법까지 한눈에 정리한 심화 가이드입니다.",
