      "요루바 이파 점복을 중심으로 바발라워, 오펠레와 이킨, 256개의 오두와 에세 이파 설화까지 깊이 다루고, 마다가스카르 시키디와 남부 아프리카 뼈점, 실전 적용법까지 살펴보는 유네스코 인류무형문화유산 아프리카 점복 전통 심화 가이드입니다.",
