<p>경계는 거리 두기가 아니라 관계를 오래 지키는 운영 규칙이다. 경계가 없는 관계는 처음에는 친밀해 보여도, 시간이 지날수록 한쪽이 지나치게 맞추거나 다른 한쪽이 지나치게 의존하는 구조로 기울기 쉽다. 반대로 다섯 가지 경계가 자연스럽게 자리 잡은 관계는 오래 함께해도 서로를 존중하는 여유가 남는다.</p>
